You can use something like this

```js
'use strict';

const common = require('../common');
const assert = require('assert');
const http = require('http');

const server = http.createServer();

server.on('upgrade', function(request, socket) {
  socket.resume();
  socket.write(
    'HTTP/1.1 101 Switching Protocols\r\n' +
    'Connection: Upgrade\r\n' +
    'Upgrade: websocket\r\n' +
    '\r\n'
  );
  socket.on('end', socket.end);
});

server.listen(0, common.mustCall(function() {
  const agent = new http.Agent({
    keepAlive: true,
    maxSockets: 1
  });

  const request = http.get({
    agent,
    headers: {
      Connection: 'upgrade',
      Upgrade: 'websocket'
    },
    port: server.address().port
  }, common.mustNotCall());

  request.on('socket', common.mustCall(function() {
    assert.strictEqual(agent.totalSocketCount, 1);
  }));

  request.on('upgrade', common.mustCall(function(response, socket) {
    assert.strictEqual(agent.totalSocketCount, 0);
    server.close();
    socket.end();
  }));
}));
```

or modify an existing test if it is cleaner.
